"""Extract likely runtime commands from project scripts."""

from __future__ import annotations

from pathlib import Path


SCRIPT_EXTENSIONS = {".bat", ".cmd", ".ps1", ".sh"}
EXCLUDED_DIRS = {".git", ".venv", "__pycache__", "node_modules", "venv"}


def run(payload: dict[str, object]) -> dict[str, object]:
    root = _resolve_scoped_root(str(payload["root"]))
    commands = []
    skipped = []
    for script in _iter_scripts(root):
        rel_path = script.relative_to(root).as_posix()
        try:
            size = script.stat().st_size
        except OSError as exc:
            skipped.append({"path": rel_path, "reason": type(exc).__name__})
            continue
        if size > 100_000:
            skipped.append({"path": rel_path, "reason": "too_large"})
            continue
        lines = script.read_text(encoding="utf-8", errors="ignore").splitlines()
        command_lines = [_clean_line(line) for line in lines]
        command_lines = [
            line
            for line in command_lines
            if line and not _is_comment(line, script.suffix.lower()) and not _is_shell_noise(line)
        ]
        commands.append(
            {
                "path": rel_path,
                "commands": command_lines[:30],
                "purpose": _purpose(rel_path, command_lines),
            }
        )
    return {"root": root.as_posix(), "commands": commands, "skipped": skipped}


def _purpose(path: str, lines: list[str]) -> str:
    name = Path(path).name.lower()
    joined = " ".join(lines).lower()
    if "run" in name or "python app.py" in joined:
        return "run_application"
    if "install" in name or "pip install" in joined:
        return "install_dependencies"
    if "rebuild" in name:
        return "rebuild_data"
    return "script"


def _clean_line(line: str) -> str:
    return line.strip().lstrip("@").strip()


def _is_comment(line: str, suffix: str) -> bool:
    lower = line.lower()
    if suffix in {".bat", ".cmd"}:
        return lower.startswith("rem ") or lower.startswith("::")
    return lower.startswith("#")


def _is_shell_noise(line: str) -> bool:
    lower = line.lower()
    return lower in {"echo off", "setlocal", "endlocal", "pause"} or lower.startswith("cd /d ")


def _iter_scripts(root: Path):
    stack = [root]
    while stack:
        current = stack.pop()
        try:
            children = sorted(current.iterdir(), key=lambda path: path.name.lower())
        except OSError:
            continue
        for item in children:
            try:
                is_dir = item.is_dir()
                is_file = item.is_file()
            except OSError:
                continue
            if is_dir:
                if item.name in EXCLUDED_DIRS or item.name.startswith("."):
                    continue
                stack.append(item)
            elif is_file and item.suffix.lower() in SCRIPT_EXTENSIONS:
                yield item


def _resolve_scoped_root(value: str) -> Path:
    raw = Path(value).expanduser()
    candidate = raw if raw.is_absolute() else Path.cwd() / raw
    resolved = candidate.resolve()
    if not resolved.exists() or not resolved.is_dir():
        raise ValueError("extract_runtime_commands root must point to an existing directory")
    allowed_roots = [Path.cwd().resolve(), Path.cwd().resolve().parent]
    if not any(_is_relative_to(resolved, allowed) for allowed in allowed_roots):
        raise ValueError("extract_runtime_commands root is outside the allowed project scope")
    return resolved


def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False

"""Compatibility parsing for Python syntax outside the host AST grammar."""

from __future__ import annotations

import ast
import re
import warnings


class ParserVersionIncompatible(SyntaxError):
    """The source is valid for a known Python grammar, but not the host parser."""

    def __init__(self, original: SyntaxError) -> None:
        super().__init__(*original.args)


def parse_compatible_source(source: str, filename: str) -> tuple[ast.AST, str | None]:
    try:
        return ast.parse(source, filename=filename), None
    except SyntaxError as error:
        if _newer_python_syntax(source, error):
            raise ParserVersionIncompatible(error) from error
        if not _looks_like_python2(source, error):
            raise
        converted = _convert_python2(source, filename)
        if converted is None:
            raise
        return ast.parse(converted, filename=filename), "python2_compatibility_ast"


def _newer_python_syntax(source: str, error: SyntaxError) -> bool:
    lines = source.splitlines()
    if not error.lineno or error.lineno > len(lines):
        return False
    line = lines[error.lineno - 1]
    return bool(
        re.match(r"^\s*(?:(?:async\s+)?def|class)\s+[A-Za-z_]\w*\s*\[", line)
        or re.match(r"^\s*type\s+[A-Za-z_]\w*(?:\s*\[.*\])?\s*=", line)
    )


def _looks_like_python2(source: str, error: SyntaxError) -> bool:
    lines = source.splitlines()
    line = lines[error.lineno - 1] if error.lineno and error.lineno <= len(lines) else ""
    return bool(
        re.search(r"python(?:2|\s+2(?:\.\d+)?)\b", source[:2000], re.IGNORECASE)
        or re.match(r"^\s*print(?:\s+|>>)(?!\s*\()", line)
        or re.match(r"^\s*except\s+[^:]+,\s*\w+\s*:", line)
        or re.match(r"^\s*raise\s+\w+\s*,", line)
        or re.search(r"<>|`[^`]+`", line)
    )


def _convert_python2(source: str, filename: str) -> str | None:
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            from lib2to3.refactor import RefactoringTool, get_fixers_from_package

            tool = RefactoringTool(get_fixers_from_package("lib2to3.fixes"))
            normalized = source if source.endswith("\n") else source + "\n"
            return str(tool.refactor_string(normalized, filename))
    except Exception:
        return None

